import { IS_NON_DIMENSIONAL } from '../constants';
import { NodeProps } from '../clone-element';

function setStyle(style, key, value) {
	if (key[0] === '-') {
		style.setProperty(key, value == null ? '' : value);
	} else if (value == null) {
		style[key] = '';
	} else if (typeof value != 'number' || IS_NON_DIMENSIONAL.test(key)) {
		style[key] = value;
	} else {
		style[key] = value + 'px';
	}
}

/**
 * Applies vnode host properties onto a DOM node.
 */
export function PropWriter() {
	this._binding = null;
	this._hydrate = false;
}

PropWriter.prototype.bindVNode = function (vnode, hydrating) {
	this._hydrate = !!hydrating;
	this._binding = new NodeProps(vnode);
};

/**
 * Set a property value on a DOM node
 * @param {PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
PropWriter.prototype.setProperty = function (dom, name, value, oldValue, isSvg) {
	let binding = this._binding;
	let vnodeRef = binding instanceof NodeProps ? binding._vnodeRef : null;
	let opts = vnodeRef && vnodeRef._options;
	let host = opts && opts._host;
	let apply = !this._hydrate || typeof value == 'function' || value == null;

	if (!apply) {
		return;
	}

	if (host) {
		host.element = dom;
		host.style = dom.style;
	}

	let target = (host && host.element) || dom;
	let styleTarget = (host && host.style) || (dom && dom.style);

	if (vnodeRef) {
		if (vnodeRef.type === 'svg') {
			isSvg = true;
		} else if (vnodeRef._parent) {
			isSvg = isSvg === true;
		}
		if (vnodeRef.props && name in vnodeRef.props) {
			value = vnodeRef.props[name];
		}
	}

	let useCapture;

	o: if (name === 'style') {
		if (typeof value == 'string') {
			styleTarget.cssText = value;
		} else {
			if (typeof oldValue == 'string') {
				styleTarget.cssText = oldValue = '';
			}

			if (oldValue) {
				for (name in oldValue) {
					if (!(value && name in value)) {
						setStyle(styleTarget, name, '');
					}
				}
			}

			if (value) {
				for (name in value) {
					if (!oldValue || value[name] !== oldValue[name]) {
						setStyle(styleTarget, name, value[name]);
					}
				}
			}
		}
	}
	// Benchmark for comparison: https://esbench.com/bench/574c954bdb965b9a00965ac6
	else if (name[0] === 'o' && name[1] === 'n') {
		useCapture =
			name !== (name = name.replace(/(PointerCapture)$|Capture$/i, '$1'));

		// Infer correct casing for DOM built-in events:
		if (name.toLowerCase() in dom) name = name.toLowerCase().slice(2);
		else name = name.slice(2);

		if (!target._listeners) target._listeners = {};
		target._listeners[name + useCapture] = value;

		let proxies = opts && opts._eventProxy;
		let handler = useCapture
			? proxies && proxies.capture
			: proxies && proxies.bubble;

		if (value) {
			if (!oldValue) {
				value._attached = Date.now();
				if (handler) target.addEventListener(name, handler, useCapture);
			} else {
				value._attached = oldValue._attached;
			}
		} else if (handler) {
			target.removeEventListener(name, handler, useCapture);
		}
	} else {
		if (isSvg) {
			// Normalize incorrect prop usage for SVG:
			// - xlink:href / xlinkHref --> href (xlink:href was removed from SVG and isn't needed)
			// - className --> class
			name = name.replace(/xlink(H|:h)/, 'h').replace(/sName$/, 's');
		} else if (
			name !== 'width' &&
			name !== 'height' &&
			name !== 'href' &&
			name !== 'list' &&
			name !== 'form' &&
			// Default value in browsers is `-1` and an empty string is
			// cast to `0` instead
			name !== 'tabIndex' &&
			name !== 'download' &&
			name !== 'rowSpan' &&
			name !== 'colSpan' &&
			name !== 'role' &&
			name in target
		) {
			try {
				target[name] = value == null ? '' : value;
				// labelled break is 1b smaller here than a return statement (sorry)
				break o;
			} catch (e) {
				if (opts && !opts._fence) {
					throw e;
				}
			}
		}

		// aria- and data- attributes have no boolean representation.
		// A `false` value is different from the attribute not being
		// present, so we can't remove it. For non-boolean aria
		// attributes we could treat false as a removal, but the
		// amount of exceptions would cost too many bytes. On top of
		// that other frameworks generally stringify `false`.

		if (typeof value == 'function') {
			// never serialize functions as attribute values
		} else if (value != null && (value !== false || name[4] === '-')) {
			target.setAttribute(name, value);
		} else {
			target.removeAttribute(name);
		}
	}
